00079 static int read_nalu(const uint8_t *stream, size_t stream_size, int pos, unsigned char *buf, size_t buf_size)
00080 {
00081     int read_size, bs_size;
00082     unsigned char b = 0;
00083 
00084     bs_size = 0;
00085     read_size = 0;
00086 
00087     // Is there a NUAL
00088     if(pos + 4 >= stream_size) {
00089         return -1;
00090     }
00091 
00092     memcpy(&bs_size, stream + pos, 4);
00093 
00094     if(pos + 4 + bs_size > stream_size) {
00095         return -1;
00096     }
00097 
00098     memcpy(buf, stream+pos+4, bs_size);
00099 
00100     return bs_size;
00101 }
