00103 static void print_stat(EVCD_STAT * stat, int ret)
00104 {
00105     int i, j;
00106 
00107     if(EVC_SUCCEEDED(ret))
00108     {
00109         if(stat->nalu_type < EVC_SPS_NUT)
00110         {
00111             v1print("%c-slice", stat->stype == EVC_ST_I ? 'I' : stat->stype == EVC_ST_P ? 'P' : 'B');
00112 
00113             v1print(" (%d bytes", stat->read);
00114             v1print(", poc=%d, tid=%d, ", (int)stat->poc, (int)stat->tid);
00115 
00116             for (i = 0; i < 2; i++)
00117             {
00118                 v1print("[L%d ", i);
00119                 for (j = 0; j < stat->refpic_num[i]; j++) v1print("%d ", stat->refpic[i][j]);
00120                 v1print("] ");
00121             }
00122         }
00123         else if(stat->nalu_type == EVC_SPS_NUT)
00124         {
00125             v1print("Sequence Parameter Set (%d bytes)", stat->read);
00126         }
00127         else if (stat->nalu_type == EVC_PPS_NUT)
00128         {
00129             v1print("Picture Parameter Set (%d bytes)", stat->read);
00130         }
00131         else if (stat->nalu_type == EVC_APS_NUT)
00132         {
00133             v1print("Adaptation Parameter Set (%d bytes)", stat->read);
00134         }
00135         else if (stat->nalu_type == EVC_SEI_NUT)
00136         {
00137             v1print("SEI message: ");
00138             if (ret == EVC_OK)
00139             {
00140                 v1print("MD5 check OK");
00141             }
00142             else if (ret == EVC_ERR_BAD_CRC)
00143             {
00144                 v1print("MD5 check mismatch!");
00145             }
00146             else if (ret == EVC_WARN_CRC_IGNORED)
00147             {
00148                 v1print("MD5 check ignored!");
00149             }
00150         }
00151         else
00152         {
00153             v0print("Unknown bitstream");
00154         }
00155 
00156         v1print("\n");
00157 
00158         //TBD the following stages need to be further hadnled in the proper places
00159         /*if(ret == EVC_OK)
00160         {
00161             v1print("\n");
00162         }
00163         else if(ret == EVC_OK_FRM_DELAYED)
00164         {
00165             v1print("--> Frame delayed\n");
00166         }
00167         else if(ret == EVC_OK_DIM_CHANGED)
00168         {
00169             v1print("--> Resolution changed\n");
00170         }
00171         else
00172         {
00173             v1print(" --> Unknown warning code = %d\n", ret);
00174         }*/
00175     }
00176     else
00177     {
00178         v0print("Decoding error = %d\n", ret);
00179     }
00180 }
