00182 static int set_extra_config(EVCD id)
00183 {
00184     int  ret, size, value;
00185 
00186     if(op_use_pic_signature)
00187     {
00188         value = 1;
00189         size = 4;
00190         ret = evcd_config(id, EVCD_CFG_SET_USE_PIC_SIGNATURE, &value, &size);
00191         if(EVC_FAILED(ret))
00192         {
00193             v0print("failed to set config for picture signature\n");
00194             return -1;
00195         }
00196     }
00197     return 0;
00198 }
