00200 static int write_dec_img(const evc_writer_t *writer, EVCD id, char * fname, EVC_IMGB * img, EVC_IMGB * imgb_t)
00201 {
00202     if(op_out_bit_depth == 8)
00203     {
00204         imgb_conv_16b_to_8b(imgb_t, img, 2);
00205         if(imgb_write_mem(writer, imgb_t)) return -1;
00206     }
00207     else
00208     {
00209         if(imgb_write_mem(writer, img)) return -1;
00210     }
00211     return EVC_OK;
00212 }
