00214 int evc_decode_mem(const uint8_t *stream, size_t stream_size, unsigned output_bit_depth, const evc_writer_t *writer)
00215 {
00216     STATES             state = STATE_DECODING;
00217     unsigned char    * bs_buf = NULL;
00218     EVCD              id = NULL;
00219     EVCD_CDSC         cdsc;
00220     EVC_BITB          bitb;
00221     EVC_IMGB        * imgb;
00222     /*temporal buffer for video bit depth less than 10bit */
00223     EVC_IMGB        * imgb_t = NULL;
00224     EVCD_STAT         stat;
00225     EVCD_OPL          opl;
00226     int                ret;
00227     EVC_CLK           clk_beg, clk_tot;
00228     int                bs_cnt, pic_cnt;
00229     int                bs_size, bs_read_pos = 0;
00230     int                w, h;
00231     FILE             * fp_bs = NULL;
00232 
00233 #if M52291_HDR_DRA
00234     int sps_dra_enable_flag = 0;
00235     int pps_dra_enable_flag = 0;
00236     EVC_IMGB          *imgb_dra = NULL;
00237     // global CVS buffer for DRA control
00238     SignalledParamsDRA g_dra_control_array[32];
00239     // local PU buffer for 2 types of APS data: ALF and DRA
00240     evc_AlfSliceParam g_alf_control;
00241     evc_AlfSliceParam *p_g_alf_control = &g_alf_control;
00242 
00243     WCGDDRAControl g_dra_control_effective;
00244     WCGDDRAControl g_dra_control_read;
00245     WCGDDRAControl *p_g_dra_control_read = &g_dra_control_read;
00246 
00247     // Structure to keep 2 types of APS to read at PU
00248     EVC_APS_GEN aps_gen_array[2];
00249     EVC_APS_GEN *p_aps_gen_array = &(aps_gen_array[0]);
00250 
00251     for (int i = 0; i < 32; i++)
00252     {
00253         g_dra_control_array[i].m_signal_dra_flag = -1;
00254     }
00255     g_dra_control_read.m_signalledDRA.m_signal_dra_flag = 0;
00256     aps_gen_array[0].aps_data = (void*)p_g_alf_control;
00257     aps_gen_array[1].aps_data = (void*)(&(g_dra_control_read.m_signalledDRA));
00258     evc_resetApsGenReadBuffer(p_aps_gen_array);
00259 #endif
00260 
00261 #if DECODING_TIME_TEST
00262     clk_beg = evc_clk_get();
00263 #endif
00264 
00265     bs_buf = malloc(MAX_BS_BUF);
00266     if(bs_buf == NULL)
00267     {
00268         v0print("ERROR: cannot allocate bit buffer, size=%d\n", MAX_BS_BUF);
00269         return -1;
00270     }
00271     id = evcd_create(&cdsc, NULL);
00272     if(id == NULL)
00273     {
00274         v0print("ERROR: cannot create EVC decoder\n");
00275         return -1;
00276     }
00277     if(set_extra_config(id))
00278     {
00279         v0print("ERROR: cannot set extra configurations\n");
00280         return -1;
00281     }
00282 
00283     pic_cnt = 0;
00284     clk_tot = 0;
00285     bs_cnt  = 0;
00286     w = h   = 0;
00287 
00288     int process_status = EVC_OK;
00289 
00290     while(1)
00291     {
00292         if (state == STATE_DECODING)
00293         {
00294             evc_mset(&stat, 0, sizeof(EVCD_STAT));
00295 
00296             bs_size = read_nalu(stream, stream_size, bs_read_pos, bs_buf, MAX_BS_BUF);
00297             int nalu_size_field_in_bytes = 4;
00298 
00299             if (bs_size <= 0)
00300             {
00301                 state = STATE_BUMPING;
00302                 v1print("bumping process starting...\n");
00303                 continue;
00304             }
00305 
00306             bs_read_pos += (nalu_size_field_in_bytes + bs_size);
00307             stat.read += nalu_size_field_in_bytes;
00308             bitb.addr = bs_buf;
00309             bitb.ssize = bs_size;
00310             bitb.bsize = MAX_BS_BUF;
00311 
00312             v1print("[%4d] NALU --> ", bs_cnt++);
00313 #if !DECODING_TIME_TEST
00314             clk_beg = evc_clk_get();
00315 #endif
00316             /* main decoding block */
00317 #if M52291_HDR_DRA
00318             ret = evcd_decode(id, &bitb, &stat, (void*)(p_aps_gen_array), (void*) (&(g_dra_control_array[0])));
00319             sps_dra_enable_flag = evcd_get_sps_dra_flag(id);
00320             if (sps_dra_enable_flag)
00321             {
00322                 // check if new DRA APS recieved, update buffer
00323                 if ((p_aps_gen_array + 1)->aps_id != -1)
00324                 {
00325                     evc_addDraApsToBuffer(&(g_dra_control_array[0]), p_aps_gen_array);
00326                 }
00327                 // Assigned effective DRA controls as specified by PPS
00328                 int pps_dra_id = evcd_get_pps_dra_id(id);
00329                 if ((pps_dra_id > -1) && (pps_dra_id < 32))
00330                 {
00331                     memcpy(&(g_dra_control_effective.m_signalledDRA), &(g_dra_control_array[pps_dra_id]), sizeof(SignalledParamsDRA));
00332                     g_dra_control_effective.m_flagEnabled = 1;
00333                     evcd_assign_pps_draParam(id, &(g_dra_control_effective.m_signalledDRA));
00334                 }
00335                 else
00336                 {
00337                     g_dra_control_effective.m_flagEnabled = 0;
00338                     g_dra_control_effective.m_signalledDRA.m_signal_dra_flag = 0;
00339                 }
00340             }
00341 #else
00342             ret = evcd_decode(id, &bitb, &stat);
00343 #endif
00344 
00345             if(EVC_FAILED(ret))
00346             {
00347                 v0print("failed to decode bitstream\n");
00348                 goto END;
00349             }
00350 
00351 #if !DECODING_TIME_TEST
00352             clk_tot += evc_clk_from(clk_beg);
00353 #endif
00354                 print_stat(&stat, ret);
00355             if(stat.read - nalu_size_field_in_bytes != bs_size)
00356             {
00357                 v0print("\t=> different reading of bitstream (in:%d, read:%d)\n",
00358                     bs_size, stat.read);
00359             }
00360 
00361             process_status = ret;
00362         }
00363         if(stat.fnum >= 0 || state == STATE_BUMPING)
00364         {
00365             ret = evcd_pull(id, &imgb, &opl);
00366             if(ret == EVC_ERR_UNEXPECTED)
00367             {
00368                 v1print("bumping process completed\n");
00369                 goto END;
00370             }
00371             else if(EVC_FAILED(ret))
00372             {
00373                 v0print("failed to pull the decoded image\n");
00374                 return -1;
00375             }
00376         }
00377         else
00378         {
00379             imgb = NULL;
00380         }
00381 
00382         if(imgb)
00383         {
00384             w = imgb->w[0];
00385             h = imgb->h[0];
00386 
00387             if(writer)
00388             {
00389                 if(op_out_bit_depth == 8 && imgb_t == NULL)
00390                 {
00391                     imgb_t = imgb_alloc(w, h, EVC_COLORSPACE_YUV420);
00392                     if(imgb_t == NULL)
00393                     {
00394                         v0print("failed to allocate temporay image buffer\n");
00395                         return -1;
00396                     }
00397                 }
00398 #if M52291_HDR_DRA
00399                 pps_dra_enable_flag = evcd_get_pps_dra_flag(id);
00400                 if ( (sps_dra_enable_flag == 1) && (pps_dra_enable_flag == 1) )
00401                 {
00402                     // Assigned effective DRA controls as specified by PPS
00403                     int pps_dra_id = evcd_get_pps_dra_id(id);
00404                     assert((pps_dra_id > -1) && (pps_dra_id < 32) && (g_dra_control_array[pps_dra_id].m_signal_dra_flag == 1));
00405                     memcpy(&(g_dra_control_effective.m_signalledDRA), &(g_dra_control_array[pps_dra_id]), sizeof(SignalledParamsDRA));
00406                     evcd_assign_pps_draParam(id, &(g_dra_control_effective.m_signalledDRA));
00407 
00408                     if (g_dra_control_effective.m_flagEnabled)
00409                     {
00410                         evcd_initDRA(&g_dra_control_effective);
00411                     }
00412                     if (g_dra_control_effective.m_flagEnabled)
00413                     {
00414                         int align[EVC_IMGB_MAX_PLANE] = { MIN_CU_SIZE, MIN_CU_SIZE >> 1, MIN_CU_SIZE >> 1 };
00415                         int pad[EVC_IMGB_MAX_PLANE] = { 0, 0, 0, };
00416                         imgb_dra = evc_imgb_create(w, h, EVC_COLORSPACE_YUV420_10LE, 0, pad, align);
00417                         if (imgb_dra == NULL)
00418                         {
00419                             v0print("Cannot get original image buffer (DRA)\n");
00420                             return -1;
00421                         }
00422                         imgb_cpy(imgb_dra, imgb);
00423                         evc_apply_dra_chroma_plane(imgb, imgb, &g_dra_control_effective, 1, TRUE/*backwardMapping == true*/);
00424                         evc_apply_dra_chroma_plane(imgb, imgb, &g_dra_control_effective, 2, TRUE /*backwardMapping == true*/);
00425                         evc_apply_dra_luma_plane(imgb, imgb, &g_dra_control_effective, 0, TRUE /*backwardMapping == true*/);
00426                         write_dec_img(writer, id, op_fname_out, imgb, imgb_t);
00427                         imgb_cpy(imgb, imgb_dra);
00428                         imgb_dra->release(imgb_dra);
00429                     }
00430                     else
00431                         write_dec_img(writer, id, op_fname_out, imgb, imgb_t);
00432                 }else
00433                     write_dec_img(writer, id, op_fname_out, imgb, imgb_t);
00434 #else
00435                 write_dec_img(writer, id, op_fname_out, imgb, imgb_t);
00436 #endif
00437             }
00438             imgb->release(imgb);
00439             pic_cnt++;
00440         }
00441         fflush(stdout);
00442         fflush(stderr);
00443     }
00444 
00445 END:
00446 #if DECODING_TIME_TEST
00447     clk_tot += evc_clk_from(clk_beg);
00448 #endif
00449     v1print("=======================================================================================\n");
00450     v1print("Resolution                        = %d x %d\n", w, h);
00451     v1print("Processed NALUs                   = %d\n", bs_cnt);
00452     v1print("Decoded frame count               = %d\n", pic_cnt);
00453     if(pic_cnt > 0)
00454     {
00455         v1print("total decoding time               = %d msec,",
00456                 (int)evc_clk_msec(clk_tot));
00457         v1print(" %.3f sec\n",
00458             (float)(evc_clk_msec(clk_tot) /1000.0));
00459 
00460         v1print("Average decoding time for a frame = %d msec\n",
00461                 (int)evc_clk_msec(clk_tot)/pic_cnt);
00462         v1print("Average decoding speed            = %.3f frames/sec\n",
00463                 ((float)pic_cnt*1000)/((float)evc_clk_msec(clk_tot)));
00464     }
00465     v1print("=======================================================================================\n");
00466 
00467     if(id) evcd_delete(id);
00468     if(imgb_t) imgb_free(imgb_t);
00469     if(fp_bs) fclose(fp_bs);
00470     if(bs_buf) free(bs_buf);
00471 
00472     return process_status;
00473 }
00474 
00475 static int imgb_write_mem(const evc_writer_t *writer, EVC_IMGB * img)
00476 {
00477     unsigned char * p8;
00478     int             i, j, bd;
00479 
00480     if(img->cs == EVC_COLORSPACE_YUV420_10LE)
00481     {
00482         bd = 2;
00483     }
00484     else if(img->cs == EVC_COLORSPACE_YUV420)
00485     {
00486         bd = 1;
00487     }
00488     else
00489     {
00490         print("cannot support the color space\n");
00491         return -1;
00492     }
00493 
00494     writer->output_begin_fn(writer->data, bd == 2, img->w[0], img->h[0]);
00495 
00496     for(i = 0; i < 3; i++)
00497     {
00498         p8 = (unsigned char *)img->a[i] + (img->s[i] * img->y[i]) + (img->x[i] * bd);
00499 
00500         for(j = 0; j < img->h[i]; j++)
00501         {
00502             writer->output_write_fn(writer->data, p8, img->w[i] * bd);
00503             p8 += img->s[i];
00504         }
00505     }
00506     writer->output_end_fn(writer->data);
00507     return 0;
00508 }
